const submissionFromLocation = () => publicBoundaryAlias() ? '1a74fdf4-4e69-4e94-945e-811f742b6c86' : new URLSearchParams(window.location.search).get('submission');
const queryResultTab = (): OutputTab => { const tab = new URLSearchParams(window.location.search).get('tab'); return tab === 'explanation' ? 'review' : ['verification', 'review', 'source'].includes(tab || '') ? tab as OutputTab : 'review'; };
